async (page) => {
  const s = page.getByTestId('search-input');
  await s.fill('Monospace Tee');
  await page.waitForURL(u => u.search.includes('Monospace'));
  await page.waitForTimeout(1500);
  const rows = await page.evaluate(() => Array.from(document.querySelectorAll('table[role=grid] tr, [role=row]')).map(r => r.textContent).slice(0,10));
  const anchor = await page.getByTestId('datagrid-row-anchor').evaluate(a => ({href: a.getAttribute('href'), style: a.getAttribute('style')}));
  return { url: page.url(), rows, anchor };
}

