async (page) => {
  await page.getByRole('main').last().waitFor();
  await page.waitForLoadState('networkidle');
  const links = await page.getByRole('link', { name: /Monospace Tee/ }).evaluateAll(as => as.map(a => ({ text: a.textContent, href: a.getAttribute('href'), tid: a.getAttribute('data-test-id') })));
