  const enabled = await save.isEnabled();
  const bar = await page.evaluate(() => Array.from(document.querySelectorAll('[data-test-id]')).filter(e => /save|button-bar|savebar|composition|steps/i.test(e.getAttribute('data-test-id'))).map(e => e.tagName + ' ' + e.getAttribute('data-test-id') + ' | ' + e.textContent.trim().slice(0,80)));
  const headerWhileDirty = await page.getByTestId('page-header').innerText();
  return { saveHtml, enabled, bar, headerWhileDirty };
}

async (page) => {
  const save = page.getByTestId('button-bar-confirm');
  await save.click();
  const notif = page.getByTestId('notification');
  await page.getByRole('region', { name: /Notifications/ }).getByText(/Saved changes|saved/i).first().waitFor();
  const notifs = await page.evaluate(() => Array.from(document.querySelectorAll('[data-sonner-toast], [data-test-id^=notification], li[role=status], [role=status]')).map(e => (e.getAttribute('data-test-id')||e.tagName) + ' | ' + e.textContent.trim().slice(0,80) + ' | ' + e.outerHTML.slice(0,200)));
  const header = await page.getByTestId('page-header').innerText();
  const state = await save.getAttribute('data-test-state');
  return { notifs, header, state, title: await page.title(), saveDisabled: await save.isDisabled() };
}

async (page) => {
