1	import { expect, test } from "../../fixtures/test.ts";
2	import { DraftOrderPage } from "../../pages/draftOrderPage.ts";
3	import { CHANNEL, ORDERS_SCENARIO, PRODUCTS, PROMOTIONS } from "../../scenarios/orders.ts";
4	
5	/**
6	 * Replaces legacy SALEOR_215 (a catalogue promotion discounts a draft line) and SALEOR_216
7	 * (an order promotion discounts a draft once its subtotal qualifies) as one story: the
8	 * second only means something on top of the first.
9	 */
10	test.use({ scenario: ORDERS_SCENARIO });
11	
12	const money = (amount: number) => amount.toFixed(2);
13	
14	test("Draft totals apply catalogue and order promotions #e2e", async ({ page }) => {
15	  // Arrange
16	  const draft = new DraftOrderPage(page);
17	  const teePrice = PRODUCTS.tee.price;
18	  const hoodiePrice = PRODUCTS.hoodie.price;
19	  const teeDiscount = (teePrice * PROMOTIONS.catalogue.percent) / 100;
20	  const subtotal = teePrice - teeDiscount + hoodiePrice;
21	  const orderDiscount = (subtotal * PROMOTIONS.order.percent) / 100;
22	
23	  // Guards the arithmetic below: the first line alone must not qualify, both together must.
24	  expect(teePrice - teeDiscount).toBeLessThan(PROMOTIONS.order.subtotalAtLeast);
25	  expect(subtotal).toBeGreaterThanOrEqual(PROMOTIONS.order.subtotalAtLeast);
26	
27	  await draft.create({ from: "drafts", channel: CHANNEL.name });
28	
29	  // Act & Assert
30	  await test.step("a line on catalogue promotion is discounted", async () => {
31	    await draft.addProduct(PRODUCTS.tee);
32	    await expect(draft.total).toHaveText(money(teePrice - teeDiscount));
33	    await expect(draft.discountToggle).toContainText(money(teeDiscount));
34	  });
35	
36	  await test.step("crossing the subtotal threshold applies the order promotion", async () => {
37	    await draft.addProduct(PRODUCTS.hoodie);
38	    await expect(draft.total).toHaveText(money(subtotal - orderDiscount));
39	    await expect(draft.discountToggle).toContainText(money(teeDiscount + orderDiscount));
40	  });
41	
42	  await test.step("the discount breakdown names both promotions' shares", async () => {
43	    await draft.discountToggle.click();
44	    await expect(draft.summary).toContainText(PROMOTIONS.order.name);
45	    await expect(draft.summary).toContainText(money(orderDiscount));
46	    await expect(draft.summary).toContainText(money(teeDiscount));
47	  });
48	});
49

1	import { expect, type Page } from "@playwright/test";
2	
3	import { AddressDialog } from "./addressDialog.ts";
4	
5	/**
6	 * A draft order, from creating it on either list to finalizing it. Ported from the
7	 * legacy `DraftOrdersPage`, `OrderCreateDialog` and `AddProductsDialog`, reworked for the
8	 * current customer flow: "Change customer" and then an address dialog, rather than a
9	 * customer search on the page itself.
10	 */
11	export class DraftOrderPage {
12	  readonly addressDialog = new AddressDialog(this.page);
13	
14	  readonly dialog = this.page.getByRole("dialog");
15	
16	  readonly createOrderButton = this.page.getByTestId("create-order-button");
17	
18	  readonly createDraftButton = this.page.getByTestId("create-draft-order-button");
19	
20	  readonly channelInput = this.page.getByTestId("channel-autocomplete");
21	
22	  readonly option = this.page.getByTestId("select-option");
23	
24	  readonly statusInfo = this.page.getByTestId("status-info");
25	
26	  readonly addProductsButton = this.page.getByTestId("add-products-button");
27	
28	  readonly productRow = this.page.getByTestId("product");
29	
30	  readonly variantRow = this.page.getByTestId("variant");
31	
32	  readonly confirmProductsButton = this.page.getByTestId("confirm-button");
33	
34	  readonly changeCustomerButton = this.page.getByTestId("change-customer");
35	
36	  readonly customerInput = this.page.getByTestId("select-customer");
37	
38	  readonly customerSection = this.page.getByTestId("customer-email-section");
39	
40	  readonly shippingAddressSection = this.page.getByTestId("shipping-address-section");
41	
42	  readonly billingAddressSection = this.page.getByTestId("billing-address-section");
43	
44	  readonly setShippingMethodButton = this.page.getByTestId("add-shipping-carrier");
45	
46	  readonly shippingMethodSelect = this.page.getByTestId("shipping-method-select");
47	
48	  readonly confirmShippingButton = this.page.getByTestId("confirm-button");
49	
50	  readonly total = this.page.getByTestId("order-total");
51	
52	  readonly discountToggle = this.page.getByTestId("discount-section-toggle");
53	
54	  readonly summary = this.page.getByTestId("OrderSummary");
55	
56	  readonly finalizeButton = this.page.getByTestId("button-bar-confirm");
57	
58	  constructor(readonly page: Page) {}
59	
60	  /** Both lists create the same draft; they differ only in where the button lives. */
61	  async create({ from, channel }: { from: "orders" | "drafts"; channel: string }) {
62	    if (from === "orders") {
63	      await this.page.goto("/orders");
64	      await this.createOrderButton.click();
65	    } else {
66	      await this.page.goto("/orders/drafts");
67	      await this.createDraftButton.click();
68	    }
69	
70	    await this.channelInput.click();
71	    await this.option.filter({ hasText: channel }).click();
72	    await this.dialog.getByTestId("submit").click();
73	    await expect(this.statusInfo).toHaveText("Draft");
74	  }
75	
76	  /**
77	   * Searches by name - the search does not match SKUs - and waits for the list to narrow to
78	   * that one product: until the search lands the list re-renders, and a checkbox ticked in
79	   * the unfiltered one is detached from under the click.
80	   */
81	  async addProduct({ name, sku }: { name: string; sku: string }) {
82	    await this.addProductsButton.click();
83	    await this.dialog.getByRole("textbox").fill(name);
84	    await expect(this.productRow).toHaveCount(1);
85	    await this.variantRow
86	      .filter({ hasText: `SKU ${sku}` })
87	      .getByRole("checkbox")
88	      .click();
89	    await this.confirmProductsButton.click();
90	    await this.dialog.waitFor({ state: "hidden" });
91	  }
92	
93	  /**
94	   * Picks an existing customer, or types an email no customer has - the picker then offers
95	   * "Use email: ...". Either way the address dialog follows.
96	   */
97	  async assignCustomer(email: string) {
98	    await this.changeCustomerButton.click();
99	    await this.customerInput.fill(email);
100	    await this.option.filter({ hasText: email }).click();
101	    await this.dialog.getByTestId("submit").click();
102	  }
103	
104	  async setFirstShippingMethod() {
105	    await this.setShippingMethodButton.click();
106	    await this.shippingMethodSelect.click();
107	    await this.option.filter({ hasNotText: "No shipping method" }).first().click();
108	    await this.confirmShippingButton.click();
109	    await this.dialog.waitFor({ state: "hidden" });
110	  }
111	
112	  /** Lands on the order it became, which no longer lives under `/orders/drafts/`. */
113	  async finalize() {
114	    await this.finalizeButton.click();
115	    await this.page.waitForURL(url => !url.pathname.includes("/drafts/"));
116	  }
117	}
