import { type Page } from "@playwright/test";

/**
 * The global Search page. It is the accessible way to a product: the Products list is a
 * canvas datagrid whose rows expose no roles, while search results are real links.
 */
export class SearchPage {
  readonly searchInput = this.page.getByTestId("search-input");

  readonly productsScope = this.page.getByRole("radio", { name: "Products", exact: true });

  constructor(readonly page: Page) {}

  /**
   * Each result row links to the product three times (kind, name, date). Filtering on the
   * exact name text picks the name link alone, and one of no other product whose name
   * merely contains it.
   */
  productLink(name: string) {
    return this.page.getByRole("link").filter({ has: this.page.getByText(name, { exact: true }) });
  }

  /** Lands on the product's detail page. */
  async openProduct(name: string) {
    await this.page.goto("/search");
    await this.searchInput.fill(name);
    await this.productsScope.click();
    await this.page.waitForURL(url => url.searchParams.get("scope") === "products");
    await this.productLink(name).click();
    await this.page.waitForURL(/\/products\/[^/]+$/);
  }
}

import { expect, type Page } from "@playwright/test";

/** A product's detail page: its header, the general information form and the save bar. */
export class ProductPage {
  readonly header = this.page.getByTestId("page-header");

  readonly titleSkeleton = this.page.getByTestId("product-details-title-skeleton");

  readonly nameInput = this.page.getByRole("textbox", { name: "Name", exact: true });

  readonly saveButton = this.page.getByTestId("button-bar-confirm");

  readonly unsavedChanges = this.page.getByTestId("product-save-composition");

  constructor(readonly page: Page) {}

  /** The header renders the name as a `title`, next to the product type chip. */
  title(name: string) {
    return this.header.getByTitle(name, { exact: true });
  }

  async waitForLoaded() {
    await this.nameInput.waitFor();
    await this.titleSkeleton.waitFor({ state: "hidden" });
  }

  async rename(name: string) {
    await this.nameInput.fill(name);
  }

  /**
   * Save stays enabled, showing a spinner, while the mutation runs, and is disabled again
   * only once the form is clean - so that, not the short-lived toast, marks completion.
   */
  async save() {
    await this.saveButton.click();
    await expect(this.saveButton).toBeDisabled();
    await this.unsavedChanges.waitFor({ state: "hidden" });
  }

  async reload() {
    await this.page.reload();
    await this.waitForLoaded();
  }
}

import { expect, test } from "../../fixtures/test.ts";
import { ProductPage } from "../../pages/productPage.ts";
import { SearchPage } from "../../pages/searchPage.ts";
import { ORDERS_SCENARIO, PRODUCTS } from "../../scenarios/orders.ts";

/**
 * Staff opens a product through the global search, renames it and saves. The header
 * follows the name only once it is saved, and the name survives a reload.
 *
 * The rename is deliberately not re-checked through search: without beat the search index
 * keeps the old name (see `e2e/README.md`).
 */
test.use({ scenario: ORDERS_SCENARIO });

const NEW_NAME = "E2E Zip Hoodie";

test("Staff renames a product #e2e", async ({ page }) => {
  // Arrange
  const search = new SearchPage(page);
  const product = new ProductPage(page);
  const oldName = PRODUCTS.hoodie.name;

  // Act & Assert
  await test.step("Staff opens the product", async () => {
    await search.openProduct(oldName);
    await product.waitForLoaded();
    await expect(product.title(oldName)).toBeVisible();
    await expect(product.nameInput).toHaveValue(oldName);
    await expect(product.saveButton).toBeDisabled();
  });

  await test.step("Staff renames it and saves", async () => {
    await product.rename(NEW_NAME);
    await expect(product.saveButton).toBeEnabled();
    await expect(product.unsavedChanges).toHaveText("Unsaved changes: details");
    // The header shows the saved name, not the edited one.
    await expect(product.title(oldName)).toBeVisible();

    await product.save();
    await expect(product.title(NEW_NAME)).toBeVisible();
    await expect(product.title(oldName)).toBeHidden();
    await expect(page).toHaveTitle(`${NEW_NAME} | Saleor e-commerce`);
  });

  await test.step("The new name persists after a reload", async () => {
    await product.reload();
    await expect(product.nameInput).toHaveValue(NEW_NAME);
    await expect(product.title(NEW_NAME)).toBeVisible();
  });
});

